import{_ as a,C as i,o as r,c as o,E as l,a2 as d}from"./chunks/framework.BOeh4kYD.js";const b=JSON.parse('{"title":"证据齐全，不等于获得执行权","description":"","frontmatter":{"title":"证据齐全，不等于获得执行权","date":"2026-09-12","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当决定行动是否获准的事实位于模型可见工作区与记忆之外时，必须向规划器暴露哪些证据才能形成有用计划；即使证据完整，仍须在变更边界执行什么安全判断？","summary":"完整证据能让规划问题变得可解，却不能自动授予执行权。受治理的数字员工必须把证据、意图和现时授权分开，并在外部效果发生前执行绑定具体行动的确定性检查。","sources":["research/analysis/Q-20260912-01-evidence-completion-not-execution-authority.md"],"item_id":"Q-20260912-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-12-evidence-complete-not-execution-authority-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-09-12-evidence-complete-not-execution-authority.md","filePath":"zh/digital-employee/2026-09-12-evidence-complete-not-execution-authority.md","lastUpdated":1789216147000}'),n={name:"zh/digital-employee/2026-09-12-evidence-complete-not-execution-authority.md"};function p(c,t,h,s,u,m){const e=i("ArticleCover");return r(),o("div",null,[l(e,{image:"/assets/covers/daily-2026-09-12-evidence-complete-not-execution-authority-cover.png",kicker:"数字员工 · 每日研究",title:"证据齐全，不等于获得执行权",summary:"完整证据能让规划问题变得可解，却不能自动授予执行权。受治理的数字员工必须把证据、意图和现时授权分开，并在外部效果发生前执行绑定具体行动的确定性检查。",version:"Q-20260912-01",status:"Daily Runtime V5 · 2026-09-12",languageHref:"/en/digital-employee/2026-09-12-evidence-complete-not-execution-authority",languageLabel:"English"}),t[0]||(t[0]=d('<h1 id="证据齐全-不等于获得执行权" tabindex="-1">证据齐全，不等于获得执行权 <a class="header-anchor" href="#证据齐全-不等于获得执行权" aria-label="Permalink to &quot;证据齐全，不等于获得执行权&quot;">​</a></h1><p>两个数字员工看到完全相同的文件、同样的完成回执和同一份待发布内容。它们甚至提出同一个动作：把结果发送到外部渠道。但其中一个会话属于当前获准的执行尝试，另一个只是恢复后留下的旧会话。</p><p>从模型视角看，两者可能没有区别；从治理视角看，安全答案必须相反。决定差异的不是文档内容，而是位于其他状态载体上的主体、尝试、范围、目标和证据代际。</p><p>本文的核心判断是：<strong>完整的权限证据可以让规划变得可行，却不能授权执行。每个重要外部效果仍需在变更边界，由绑定当前意图的确定性检查单独决定是否允许发生。</strong></p><h2 id="三个经常被压成一个的问题" tabindex="-1">三个经常被压成一个的问题 <a class="header-anchor" href="#三个经常被压成一个的问题" aria-label="Permalink to &quot;三个经常被压成一个的问题&quot;">​</a></h2><p>执行型智能体至少要回答三个不同问题：</p><ol><li>规划器是否看到了足够事实，能够理解当前状态；</li><li>规划器具体提出了什么动作；</li><li>当前权威来源是否允许这个动作在这个目标上、由这个主体、于这次尝试中发生。</li></ol><p>第一个问题关乎证据完整性，第二个关乎模型能力，第三个才是执行授权。把三者合并，会让“模型知道规则”悄悄变成“模型拥有批准权”。</p><h2 id="消融实验揭示的是信息边界" tabindex="-1">消融实验揭示的是信息边界 <a class="header-anchor" href="#消融实验揭示的是信息边界" aria-label="Permalink to &quot;消融实验揭示的是信息边界&quot;">​</a></h2><p>同日研究对象分析的交叉载体权威研究，先做了匹配的证据消融。看不到关键权限事实的条件在 32 次测试中得到 0 次最终语义成功；提供原始回执后是 32/32；把相同信息整理成类型化关系后仍是 32/32。</p><p>这个结果说明，缺失权威事实会让正确解释在测试任务中变得不可能。它也同时给出一个重要负结果：当信息量保持相等，类型化包装没有超过原始回执。结构可以改善校验、集成和审计，却不能凭格式本身制造新的语义准确率。</p><p>所以，第一步不是要求模型“更谨慎”，而是确认决定性事实是否真的进入了规划器可见证据。</p><h2 id="看见全部证据-规划仍可能失败" tabindex="-1">看见全部证据，规划仍可能失败 <a class="header-anchor" href="#看见全部证据-规划仍可能失败" aria-label="Permalink to &quot;看见全部证据，规划仍可能失败&quot;">​</a></h2><p>第二组实验移除了信息缺口，却没有消除模型的不确定性。原始回执条件下，首个动作有 19/32 正确；类型化关系条件下是 15/32，并出现 11/32 个无效或缺失输出。在 16 个跨界发布场景中，模型提出了 6 个不安全的交叉发布动作。</p><p>这排除了一个常见捷径：只要把政策、回执和关系都塞进上下文，就把模型输出直接接到外部工具。完整上下文让问题可解，不保证这一轮规划器一定解对，更不保证它会产生可执行动作。</p><p>规划器的职责应是形成一个明确、可检查的意图，而不是替系统补造缺失授权。</p><h2 id="冻结意图后-才能看清执行闸门的贡献" tabindex="-1">冻结意图后，才能看清执行闸门的贡献 <a class="header-anchor" href="#冻结意图后-才能看清执行闸门的贡献" aria-label="Permalink to &quot;冻结意图后，才能看清执行闸门的贡献&quot;">​</a></h2><p>第三组实验没有再调用模型，而是重放前一组完全相同的 32 个首个动作意图。确定性执行闸门把 6 个不安全跨界效果降为 0，同时放行了固定集合中全部 12 个有效且获准的发布意图。</p><p>由于意图被冻结，安全改善不能归因于更好的提示词或第二次模型判断。贡献来自变更前的外部检查：重新读取主体、会话、尝试、工件、作用域、当前工作区摘要、终态、下游使用授权和证据代际，再决定执行或记录 HOLD（安全搁置）。</p><p>但还有 4 个本应对齐的场景缺少有效规划意图。闸门阻止了危险效果，却没有替规划器完成任务。这正是安全性与可用性的边界。</p><h2 id="一份可审计的执行合同需要哪些身份" tabindex="-1">一份可审计的执行合同需要哪些身份 <a class="header-anchor" href="#一份可审计的执行合同需要哪些身份" aria-label="Permalink to &quot;一份可审计的执行合同需要哪些身份&quot;">​</a></h2><p>“文件相同”只是工件身份相同。执行合同还需分别保存：</p><table tabindex="0"><thead><tr><th>身份</th><th>需要绑定的内容</th><th>防止的误判</th></tr></thead><tbody><tr><td>工件身份</td><td>精确字节或外部对象</td><td>把相似内容当成同一对象</td></tr><tr><td>证据身份</td><td>主体、尝试、范围、终态、代际的回执</td><td>用不完整证据推断权威</td></tr><tr><td>观察身份</td><td>实际暴露给规划器的证据集合</td><td>假设模型看见了系统知道的一切</td></tr><tr><td>意图身份</td><td>动作、目标和具体发生次数</td><td>把旧批准复用于新动作</td></tr><tr><td>授权身份</td><td>当前政策对该意图的决定</td><td>把历史许可当成永久能力</td></tr><tr><td>HOLD 身份</td><td>被拒绝的意图及非效果证明</td><td>把安全阻止说成业务完成</td></tr><tr><td>结果身份</td><td>完成、失败、阻止或部分结果</td><td>混淆门禁与业务结果</td></tr></tbody></table><p>检查必须位于效果仍能被阻止的最后边界。若先发送、写入或发布，再验证权限，审计再完整也只是事故记录。</p><h2 id="委派让-当前-变得更复杂" tabindex="-1">委派让“当前”变得更复杂 <a class="header-anchor" href="#委派让-当前-变得更复杂" aria-label="Permalink to &quot;委派让“当前”变得更复杂&quot;">​</a></h2><p>对比研究 Bounded Agents（有界智能体授权框架）展示了另一层问题：权威会沿主体链委派，并受累计预算、既往动作和组合限制约束。父级拥有的能力不能简单复制给子级；一次批准也不应泛化成对相似动作的长期通行证。</p><p>因此，执行检查不能只问“这个主体是否有某个能力”。它还要确认授权链是否有效、范围是否逐级收窄、累计状态是否越界、批准是否绑定精确动作实例，以及重试是否仍属于同一次效果。</p><p>即使所有检查都由确定性代码完成，也不能假设政策天然完整。观察不到的事实、缺失的限制分类或受损的权威存储，仍会让一个可重复的闸门稳定地作出错误决定。</p><h2 id="安全阻止不是业务完成" tabindex="-1">安全阻止不是业务完成 <a class="header-anchor" href="#安全阻止不是业务完成" aria-label="Permalink to &quot;安全阻止不是业务完成&quot;">​</a></h2><p>HOLD 可以证明系统没有跨过危险边界，却不能证明用户要的结果已经产生。把两者都写成“成功”，会在恢复时制造更严重的问题：后续流程可能认为外部效果已经存在，也可能在没有非效果证明时盲目重试。</p><p>更准确的终态需要同时保留两条事实：执行门禁按规则工作；业务目标没有完成。恢复逻辑再依据外部效果“已证明不存在、已证明存在、状态未知”选择重试、对账或人工处理。</p><h2 id="可以落地的设计原则" tabindex="-1">可以落地的设计原则 <a class="header-anchor" href="#可以落地的设计原则" aria-label="Permalink to &quot;可以落地的设计原则&quot;">​</a></h2><p>受治理的执行型智能体可以采用以下最小规则：</p><ul><li>权威回执保存在可变对话记忆之外；</li><li>只向规划器暴露形成有用意图所需的证据，不把暴露本身视为许可；</li><li>授权绑定主体、尝试、工件、目标、动作范围和证据代际；</li><li>在变更发生前重新读取当前权威状态；</li><li>拒绝以显式非效果和原因持久化；</li><li>分开记录证据完整性、规划质量、执行授权和业务完成；</li><li>重试必须证明旧效果是否发生，不能仅凭超时推断；</li><li>审计不仅检查代码路径是否确定，还检查它是否看到了全部政策相关载体。</li></ul><h2 id="边界与待解决问题" tabindex="-1">边界与待解决问题 <a class="header-anchor" href="#边界与待解决问题" aria-label="Permalink to &quot;边界与待解决问题&quot;">​</a></h2><p>现有证据来自受控发布与代码场景、两条模型路线和固定矩阵，不能证明所有工具与组织都具备相同风险分布。实验信任权限数据库、主体分配和加密身份；这些层被攻破时，变更边界也会读取错误事实。</p><p>并非所有权威信息都需要进入模型上下文。某些字段可以只供执行器使用，只要规划器仍能提出足够具体且安全可判定的意图。真正要优化的是“充分的规划证据”与“完整的执行证据”，而不是最大化披露。</p><p>仍待回答的问题包括：多步动作的目标变化时如何绑定批准；什么事件使证据代际递增；并发智能体怎样预留权威；权限存储如何独立证明；以及安全 HOLD 后，应由谁、依据什么新证据重新启动任务。</p><p><strong>证据与引用：</strong></p><ul><li><a href="https://arxiv.org/html/2609.08472" target="_blank" rel="noreferrer">交叉载体权威控制研究</a></li></ul>',40))])}const y=a(n,[["render",p]]);export{b as __pageData,y as default};
